import Foundation

// Domains the bundled lists block outright, or only below, generated by scripts/tracker-domains.py.
nonisolated struct TrackerDomains: Sendable {
    private let domains: Set<String>

    init(contentsOf url: URL) throws {
        domains = Set(try String(contentsOf: url, encoding: .utf8).split(separator: "\n").map(String.init))
    }

    @concurrent static func bundled() async -> TrackerDomains {
        try! TrackerDomains(contentsOf: Bundle.main.url(forResource: "tracker-domains", withExtension: "txt")!)
    }

    // The host or one of its parent domains, short of the bare top-level domain. An entry with a leading dot matches
    // the domain's proper subdomains only: at each dot, what follows it is a parent of the host.
    func contains(host: String) -> Bool {
        var rest = Substring(host)
        while let dot = rest.firstIndex(of: ".") {
            if domains.contains(String(rest)) || domains.contains(String(rest[dot...])) { return true }
            rest = rest[rest.index(after: dot)...]
        }
        return false
    }
}
